Here's an example of simulating natural selection using MATLAB:

```matlab
% Parameters
N = 100; % Total population size
p_survival_brown = 0.9; % Survival probability for brown individuals
p_survival_white = 0.8; % Survival probability for white individuals
p_mutation = 0.01; % Probability of mutating from brown to white or vice versa

% Initial population
population(1:N, 1) = 'Brown'; % Fur color
for I = N+1:2*N
    population(i, 1) = 'White'; % Fur color
end

% Simulation loop
generations = 0;
while true
    generations = generations + 1;

    % Calculate number of survivors
    num_survivors_brown = floor(p_survival_brown * length(population(population == 'Brown', :)));
    num_survivors_white = floor(p_survival_white * length(population(population == 'White', :)));

    % Generate offspring
    new_population = zeros(2*N, 1);
    new_population(1:num_survivors_brown) = population(1:num_survivors_brown, :)';
    new_population(num_survivors_brown+1:2*N) = population(num_survivors_brown+1:2*N, :)' .* rand(size(population(num_survivors_brown+1:2*N, :))') .<= p_mutation;

    % Update population
    population = new_population;

    % Check if equilibrium has been reached
    if abs(length(population(population == 'Brown', :))) - N*p_survival_brown) <= 1 && abs(length(population(population == 'White', :))) - N*(1-p_survival_white)) <= 1
        disp(['Equilibrium reached after ' num2str(generations) ' generations.']);

