```javascript
// JavaScript function to calculate factorial
function factorial(n) {
  if (n <= 1) {
    return 1;
  } else {
    return n * factorial(n - 1);
  }
}

// Rust function to calculate factorial
fn factorial(n: u32) -> u32 {
  if n <= 1 {
    1
  } else {
    n * factorial(n - 1)
  }
}

