```javascript
const redis = require('redis');

class RedisClient {
  constructor() {
    this.client = new redis();
    this.client.on('error', (err) => {
      console.error(`Redis client not connected to the server: ${err}`);
    });
  }

  isAlive() {
    return this.client.ping().then(() => true).catch(() => false);
  }

  async get(key) {
    const result = await this.client.get(key);
    return result;
  }

  async set(key, value, ttl) {
    await this.client.setex(key, ttl, value);
  }

  async del(key) {
    await this.client.del(key);
  }
}

const redisClient = new RedisClient();
module.exports = redisClient;
```

The `set` method uses the `SETEX` command to set the key with a value and an expiration time in seconds. If you don't want to set a TTL, you can simply pass `0` as the second argument. The `SET` command can also be used instead, but then you would need to call `expire` separately to set the TTL.

Note that I'm using `async/await` syntax, but you could also use callbacks or promises if preferred. Also, make sure to replace `require('redis')` with your preferred Redis library for Node.js.

